import assert from 'node:assert/strict';
import {OpeningSequence} from '../../../../src/js/cinematics/OpeningSequence.js';
import {ToyRoomIntroduction} from '../../../../src/js/cinematics/ToyRoomIntroduction.js';
import {ToyRoomStory,createToyRoomStoryState} from '../../../../src/js/toy-room/ToyRoomStory.js';
import {beginDialogueFrame,endDialogueFrame,offerDialogue,installDialogueAdvance} from '../../../../src/js/narrative/DialogueFlow.js';
const opening=new OpeningSequence({storage:null});opening.start({replay:true});opening.update(240);assert.equal(opening.time,4);for(const t of [10,14,21,25,29]){assert.equal(opening.advanceDialogue(),true);assert.equal(opening.time,t);}assert.equal(opening.advanceDialogue(),false,'Ações sem balão não são puladas');
const intro=new ToyRoomIntroduction();intro.start();intro.time=3.31;assert.ok(intro.dialogue);intro.advanceDialogue();assert.equal(intro.stage.id,'TR_005');intro.advanceDialogue();assert.equal(intro.stage.id,'TR_006');intro.advanceDialogue();assert.ok(intro.stage.time>=3.9);intro.advanceDialogue();assert.equal(intro.stage.id,'TR_007');
const story=Object.create(ToyRoomStory.prototype);story.state=createToyRoomStoryState();story.state.returnDialogueElapsed=0;assert.ok(story.advanceDialogue());assert.equal(story.state.returnDialogueElapsed,90);story.advanceDialogue();assert.equal(story.state.returnDialogueElapsed,360);story.state.investigationStage='INVESTIGATION';story.advanceDialogue();assert.equal(story.state.investigationElapsed,180);story.state.investigationStage='PICKUP';story.advanceDialogue();assert.equal(story.state.swordPickupElapsed,120);story.advanceDialogue();assert.equal(story.state.swordPickupElapsed,300);
const canvas=new EventTarget();let advances=0,actions=0;const remove=installDialogueAdvance(canvas,{advance:()=>{advances++;return true;}});canvas.addEventListener('pointerdown',()=>actions++);beginDialogueFrame(canvas);offerDialogue(canvas,'Fala');endDialogueFrame(canvas);canvas.dispatchEvent(new Event('pointerdown',{cancelable:true}));assert.equal(advances,1);assert.equal(actions,0,'Leitura consome entrada antes de gameplay');beginDialogueFrame(canvas);endDialogueFrame(canvas);canvas.dispatchEvent(new Event('pointerdown'));assert.equal(actions,1,'Sem diálogo a ação continua disponível');remove();
console.log('APROVADO: abertura e sala por clique, narrador/personagem/espada, gestos sem fala preservados, entrada consumida e liberada fora dos diálogos.');
